                        let update = self.doc.transact().encode_state_as_update_v1(&sv);
                        replies.push(sync(SyncMessage::SyncStep2(update)));
                    }
                    SyncMessage::SyncStep2(u) | SyncMessage::Update(u) => {
                        self.doc
                            .transact_mut()
                            .apply_update(Update::decode_v1(&u).unwrap())
                            .unwrap();
