fn board_id(path: &str) -> Option<&str> {
    let id = path.strip_prefix("/api/boards/")?.strip_suffix("/ws")?;
    let valid = !id.is_empty()
        && id.len() <= 64
        && id
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-');
